using System;using System.Linq;using System.Reflection;using System.IO;using Verse;using Verse.AI;using Verse.AI.Group;using RimWorld;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;foreach(var w in Find.WindowStack.Windows.OfType<Dialog_MiniGame>().ToList())w.Close();TogetherMatch.Reset();TogetherInvite.Reset();foreach(var q in Find.CurrentMap.mapPawns.FreeColonistsSpawned.ToList()){q.jobs.EndCurrentJob(JobCondition.InterruptForced);q.drafter.Drafted=true;}PRMod.Settings.playTogetherInvites=true;var map=Find.CurrentMap;var b=(Thing)Host.State["chess"];var s=GameEntry.SessionFor(b);if(s!=null)GameComponent_Recreation.Current.Remove(s);var fac=((Pawn)Host.State["guest"]).Faction;var guest=PawnGenerator.GeneratePawn(PawnKindDef.Named("Villager"),fac);guest.Name=new NameSingle("R2 Guest");GenSpawn.Spawn(guest,b.Position+new IntVec3(-5,0,-4),map);guest.needs.food.CurLevelPercentage=1;guest.needs.rest.CurLevelPercentage=1;LordMaker.MakeNewLord(fac,new LordJob_VisitColony(fac,b.Position,30000),map,new[]{guest});Host.State["guestR2"]=guest;var game=b.TryGetComp<CompMiniGame>().Game;bool sent=(bool)typeof(TogetherInvite).GetMethod("Invite",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{game,b,guest});string log=Host.Root+"/guest-r2.txt";File.WriteAllText(log,"fresh Villager, real VisitColony Lord, joy="+guest.needs.joy+" sent="+sent+"\n");int start=Find.TickManager.TicksGame,last=-1;Host.Watch=()=>{int e=Find.TickManager.TicksGame-start;if(e/500!=last){last=e/500;File.AppendAllText(log,e+" job="+guest.CurJobDef+" waiting="+TogetherInvite.IsWaiting(guest)+" alone="+TogetherInvite.IsAlone(guest)+" at="+guest.Position+" duty="+guest.mindState.duty?.def+" report="+guest.jobs.curDriver?.GetReport()+"\n");}if(e>10400){Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Observe full 2h wait -> 2h solo -> release without skipping expiry timers.";}}

